insert into programs(school_id,name,field,level,mode,duration_years,foundation_available,english_test_waiver,verified,demo,entry_note,intl_source_url,internal_note)
select s.sid::uuid, v.name, v.field, case v.lv when 'U' then 'Undergraduate' when 'M' then 'Masters' else 'Graduate Certificate' end, 'Regular', v.dur::numeric, false,false,false,false,
 case v.lang when 'F' then 'Taught in French.' when 'B' then 'Offered in English and French.' end, nullif(u.url,''),
 'Program list taken from the school''s official website (Canada load, Nov 2026).'
from v join s on s.i=v.si join u on u.i=v.ui
where not exists (select 1 from programs x where x.school_id=s.sid::uuid and lower(x.name)=lower(v.name) and x.level=case v.lv when 'U' then 'Undergraduate' when 'M' then 'Masters' else 'Graduate Certificate' end);
